// TICachePivot — collapse cache rows to per-source hit flags (single item)
const rows = $input.all().map(i => i.json).filter(r => r && r.source);
const g = (s) => { const r = rows.find(x => x.source === s); return (r && r.result) ? 'hit' : null; };
return [{ json: { cache_vt_ip: g('virustotal_ip'), cache_abuse: g('abuseipdb'), cache_file: g('virustotal_file'), cache_url: g('virustotal_url') } }];

// TIMerge — cache-aware TI (fresh ?? cached ?? UNKNOWN)
const ctx = $('EnrichmentTrigger').first().json;
const rows = {};
try { $('TICacheRead').all().forEach(i => { rows[i.json.source] = i.json; }); } catch (e) {}
function pick(nodeName, source) {
  try {
    const j = $(nodeName).first().json;
    if (j && j.data) return { v: j, from: 'live', at: new Date().toISOString() };
  } catch (e) {}
  try {
    const r = rows[source];
    if (r && r.result) return { v: r.result, from: 'cache', at: r.fetched_at };
  } catch (e) {}
  return { v: null, from: 'none', at: null };
}
function vtStats(body) { try { const s = body.data.attributes.last_analysis_stats; return { malicious: s.malicious || 0, suspicious: s.suspicious || 0, harmless: s.harmless || 0 }; } catch (e) { return 'UNKNOWN'; } }
function abStats(body) { try { const d = body.data; return { confidence: d.abuseConfidenceScore, country: d.countryCode, reports: d.totalReports }; } catch (e) { return 'UNKNOWN'; } }

function pickRaw(nodeName, source, probe) {
  try { const j = $(nodeName).first().json; if (j && !j.error && (probe(j))) return { v: j, from: 'live' }; } catch (e) {}
  try { const r = rows[source]; if (r && r.result && probe(r.result)) return { v: r.result, from: 'cache' }; } catch (e) {}
  return { v: null, from: 'none' };
}
function urlhausInfo(b) {
  try {
    const u = (b || {});
    const tags = Array.isArray(u.tags) ? u.tags.join(' ') : '';
    const threat = u.threat || 'unknown';
    let status = u.url_status || 'unknown';
    // Surface a confirmed threat verdict inside url_status so the existing
    // downstream keyword guard (/malware|phish/ on url_status) counts true
    // threats. Pure online/offline without a threat verdict keeps its plain
    // status and scores 0 (partial credit deferred to workflow 01 owner).
    const sig = (/malware|phish/i.test(String(threat)) ? String(threat).toLowerCase() : (/malware|phish/i.test(tags) ? (tags.match(/malware|phish\w*/i) || [''])[0].toLowerCase() : ''));
    if (u.query_status === 'ok' && sig && status !== 'unknown') status = status + ':' + sig;
    return { url_status: status, query_status: u.query_status || 'unknown', threat: String(threat) };
  } catch (e) { return 'UNKNOWN'; } }
function otxInfo(b) { try { return { pulses: (((b || {}).pulse_info || {}).count) || 0 }; } catch (e) { return 'UNKNOWN'; } }
const p_urlhaus = pickRaw('TI_URLhaus', 'urlhaus', function (j) { return j.query_status; });
const p_otx = pickRaw('TI_OTX', 'otx_ip', function (j) { return j.pulse_info || j.base_indicator; });
const p_ip = pick('TI_VirusTotal', 'virustotal_ip');
const p_ab = pick('TI_AbuseIPDB', 'abuseipdb');
const p_vf = pick('TI_VTFile', 'virustotal_file');
const p_u = pick('TI_URL', 'virustotal_url');
const vtInfo = vtStats(p_ip.v), abInfo = abStats(p_ab.v), vfInfo = vtStats(p_vf.v), urlInfo = vtStats(p_u.v);
const ti = [{ indicator: ctx.src_ip, type: 'ipv4', sources: { virustotal: vtInfo, abuseipdb: abInfo, otx: otxInfo(p_otx.v) }, cached: (p_ip.from === 'cache' || p_ab.from === 'cache'), checked_at: new Date().toISOString() }];
const _h = ((ctx.observables || {}).hash) || '';
if (_h) ti.push({ indicator: _h, type: 'file_hash', sources: { virustotal: vfInfo }, cached: (p_vf.from === 'cache'), checked_at: p_vf.at || new Date().toISOString() });
const _urls = (((ctx.observables || {}).urls) || []);
if (_urls.length) ti.push({ indicator: _urls[0], type: 'url', sources: { virustotal: urlInfo, urlhaus: urlhausInfo(p_urlhaus.v) }, cached: (p_u.from === 'cache'), checked_at: p_u.at || new Date().toISOString() });
return [{ json: Object.assign({}, ctx, { threat_intel: ti }) }];

// AttachRelatedTI — merge cached verdicts for related IPs (no new quota)
const main = $('TIMerge').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.indicator);
const related_ti = rows.map(r => {
  let res = r.result;
  if (typeof res === 'string') { try { res = JSON.parse(res); } catch (e) { res = null; } }
  let v = 'UNKNOWN';
  try { const s = res.data.attributes.last_analysis_stats; v = { malicious: s.malicious || 0, suspicious: s.suspicious || 0 }; } catch (e) {}
  return { indicator: r.indicator, virustotal: v };
});
return [{ json: Object.assign({}, main, { related_ti: related_ti }) }];

// PrepOTX — sql-safe bundle for cache write
const j = $input.first().json || {};
const ip = String(($('EnrichmentTrigger').first().json.src_ip) || '');
if (!ip || (j && j.error) || !(j.pulse_info || j.base_indicator)) return [{ json: { indicator_q: '', result_b64: '' } }];
const indicator_q = ip.replace(/'/g, "''");
return [{ json: { indicator: ip, indicator_q: indicator_q, result_b64: Buffer.from(JSON.stringify(j)).toString('base64') } }];

// PrepURLhaus — sql-safe bundle for cache write
const j = $input.first().json || {};
const url = String(((($('EnrichmentTrigger').first().json.observables || {}).urls) || [''])[0]);
if (!url || (j && j.error) || !j.query_status || j.query_status === 'http_post_expected') return [{ json: { indicator_q: '', result_b64: '' } }];
const indicator_q = url.replace(/'/g, "''");
return [{ json: { indicator: url, indicator_q: indicator_q, result_b64: Buffer.from(JSON.stringify(j)).toString('base64') } }];

// RestoreItem — HTTP error nodes (continueRegularOutput) replace the flow item with {error};
// restore the original alert item so downstream (IFs/TIMerge) keeps rule_level, observables, etc.
return [{ json: $('EnrichmentTrigger').first().json }];

// SanitizeInput — producer-side SQL escaping (F3 fix, mirrors 01 qx pattern).
// Derives *_q twins with single-quotes doubled (SQL escape for a literal
// quote). null/undefined -> '' (matches n8n empty rendering). Downstream
// Postgres nodes MUST use the twins, never the raw fields.
// Originals pass through untouched (TI lookups keep full fidelity).
const t = $('EnrichmentTrigger').first().json;
function qx(v) { return (v === null || v === undefined) ? '' : String(v).replace(/'/g, "''"); }
const obs = (t.observables && typeof t.observables === 'object') ? t.observables : {};
const urls = Array.isArray(obs.urls) ? obs.urls : [];
const out = Object.assign({}, t, {
  src_ip_q: qx(t.src_ip),
  agent_name_q: qx(t.agent_name),
  dst_user_q: qx(t.dst_user),
  timestamp_q: qx(t.timestamp),
  hash_q: qx(obs.hash || ''),
  url_q: qx(urls[0] || '')
});
return [{ json: out }];
